type AccountPlan string

// AccountStatus defines model for Account.Status.
type AccountStatus string

// AccountSettings defines model for AccountSettings.
type AccountSettings struct {
	CreatedAt time.Time `json:"created_at"`

	// FromEmail The default From address for new campaigns.
	//
	// Examples: news@patsbakery.example
	FromEmail *string `json:"from_email"`

	// FromName The default From name for new campaigns.
	//
	// Examples: Pat's Bakery
	FromName *string `json:"from_name"`
	Id       string  `json:"id"`

	// MissingForSend Settings a campaign can't launch without, such as `postal_address`. Empty when none are missing.
	MissingForSend []string            `json:"missing_for_send"`
	Name           string              `json:"name"`
	Plan           AccountSettingsPlan `json:"plan"`

	// PostalAddress The mailing address in every email's footer, one line per `\n`.
	//
	// Examples: Pat's Bakery
	// 12 Main St
	// Springfield, IL 62701
	PostalAddress *string `json:"postal_address"`

	// SendLimit How many campaign recipients the account may send to in 24 hours.
	// New accounts start low and double each week of clean sending up to
	// the usual limit. A campaign whose spam complaints or hard bounces
	// pass the early-warning limits (0.05% and 2% by default) lowers it to
	// the new-account limit for 7 days.
	SendLimit SendLimit `json:"send_limit"`

	// SendingMode `test` while the account is in test mode (MG-80): it sends only to
	// its confirmed test addresses (`listTestAddresses`) and its owner's
	// own sign-in address. Launches and test sends to anyone else are
	// refused with the code `test_mode`, and its forms take signups only
	// from those addresses. mailgoose staff allow `full` sending.
	SendingMode SendingMode `json:"sending_mode"`

	// SendingSlug The account's name on mailgoose's shared sending domain (MG-85),
	// made from the account's name when it was created. It doesn't
	// change when the account is renamed.
	//
	//
	// Examples: pats-bakery
	SendingSlug string `json:"sending_slug"`

	// SharedAddress Where the account's email goes from when its From isn't on a
	// verified domain of its own (MG-85): `sending_slug` at mailgoose's
	// shared sending domain, with replies to the From address, which
	// has to be the owner's own sign-in address or a confirmed sender
	// address (`listSenderAddresses`). Null when the server has shared
	// sending off, and every From needs a verified domain. A custom
	// domain is optional, but better for deliverability and trust.
	//
	//
	// Examples: pats-bakery@send.mailgoose.example
	SharedAddress *string `json:"shared_address"`

	// Terms Which version of mailgoose's terms the account accepted, and the
	// version in force now. Versions are dates, `YYYY-MM-DD`; what changed
	// in each is on the web app's `/policies/changes` page.
	Terms TermsStatus `json:"terms"`

	// Tester The account's tester state when it's a tester account (MG-86); null otherwise.
	Tester *TesterStatus `json:"tester"`

	// TimeZone An IANA time zone name.
	//
	// Examples: America/Chicago
	TimeZone string `json:"time_zone"`
}

